import glob, json, os, runpy, sys
def _find():
    r = os.environ.get("SPINDOCTOR_QWERTY_ROOT")
    if r: return [r]
    home = os.path.join(os.path.expanduser("~"), ".factory", "plugins")
    c = []
    for f in glob.glob(os.path.join(home, "installed_plugins", "*.json")):
        try: d = json.load(open(f, encoding="utf-8"))
        except Exception: continue
        e = d.get("entry") or {}
        if str(d.get("pluginId", "")).split("@")[0] == "spindoctor-qwerty" and e.get("installPath"): c.append((str(e.get("lastUpdated", "")), e["installPath"]))
    c = [p for _, p in sorted(c, reverse=True)]
    g = glob.glob(os.path.join(home, "cache", "*", "spindoctor-qwerty-*", "*"))
    return c + sorted(g, key=os.path.getmtime, reverse=True)
for _r in _find():
    _s = os.path.join(_r, "skills", "spindoctor-qwerty", "scripts", "spindoctor_mcp.py")
    if os.path.isfile(_s):
        sys.argv = [_s]; runpy.run_path(_s, run_name="__main__"); break
else:
    sys.exit("spindoctor-qwerty: plugin folder not found; install it with droid plugin install, or set SPINDOCTOR_QWERTY_ROOT to the plugin folder")
